import{c as i,Q as e,j as l,m as s}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"WebUI 管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/webui.md","filePath":"guide/webui.md","lastUpdated":1779872391000}'),t={name:"guide/webui.md"};function h(n,a,r,o,d,p){return e(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="webui-管理" tabindex="-1">WebUI 管理 <a class="header-anchor" href="#webui-管理" aria-label="Permalink to &quot;WebUI 管理&quot;">​</a></h1><p>白鹿工作流提供了一个现代化的 Web 管理界面，可以直观地管理工作流、组件和配置。</p><h2 id="启动-webui" tabindex="-1">启动 WebUI <a class="header-anchor" href="#启动-webui" aria-label="Permalink to &quot;启动 WebUI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bailu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>浏览器会自动打开 <code>http://localhost:3000</code>。</p><h2 id="页面说明" tabindex="-1">页面说明 <a class="header-anchor" href="#页面说明" aria-label="Permalink to &quot;页面说明&quot;">​</a></h2><h3 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h3><p>工作区是 WebUI 的首页，展示：</p><ul><li>AI 工具状态卡片</li><li>当前项目信息</li><li>系统信息</li><li>工作流快速安装</li></ul><h3 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h3><p>管理工作流的安装和配置：</p><ul><li>查看已安装的工作流</li><li>安装新的工作流</li><li>查看工作流详情</li></ul><h3 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h3><p>查看和管理各类组件：</p><ul><li>Skills（技能）</li><li>Commands（命令）</li><li>Agents（代理）</li><li>Hooks（钩子）</li><li>Rules（规则）</li><li>MCP（模型上下文协议）</li></ul><h3 id="ai-工具" tabindex="-1">AI 工具 <a class="header-anchor" href="#ai-工具" aria-label="Permalink to &quot;AI 工具&quot;">​</a></h3><p>管理 AI 编程工具配置：</p><ul><li>查看已配置的工具</li><li>安装工具配置</li><li>查看组件统计</li></ul><h3 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h3><p>管理项目路径和 Rules 配置：</p><ul><li>添加/删除项目</li><li>设置当前项目</li><li>管理项目 Rules</li></ul><h3 id="安全审计" tabindex="-1">安全审计 <a class="header-anchor" href="#安全审计" aria-label="Permalink to &quot;安全审计&quot;">​</a></h3><p>对已安装的组件进行安全审计：</p><ul><li>检查安全漏洞</li><li>查看信任分数</li><li>查看审计详情</li></ul><h2 id="自定义端口" tabindex="-1">自定义端口 <a class="header-anchor" href="#自定义端口" aria-label="Permalink to &quot;自定义端口&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bailu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span></span></code></pre></div><h2 id="局域网访问" tabindex="-1">局域网访问 <a class="header-anchor" href="#局域网访问" aria-label="Permalink to &quot;局域网访问&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bailu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div>',28)])])}const b=i(t,[["render",h]]);export{c as __pageData,b as default};
